// _codec_cloneMapStringCodecToken returns a copy of x, a
// map[string]codec.Token, and nil for a nil x.
func _codec_cloneMapStringCodecToken(x map[string]codec.Token) map[string]codec.Token {
	if x == nil {
		return nil
	}
	c := make(map[string]codec.Token, len(x))
	for mk, mv := range x {
		c[strings.Clone(mk)] = mv
	}
	return c
}

