// _codec_putExternalCode writes the encoding of the external.Code that x points
// at into the end of buf, which has room for it, and returns its length. It
// fails when x fails to encode itself.
func _codec_putExternalCode(buf []byte, x *external.Code, loc string, num int) (int, error) {
	enc, err := x.MarshalBinary()
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	return copy(buf[len(buf)-len(enc):], enc), nil
}

